#[inline]
pub fn glyph_index(ch: char) -> usize {
    let code = ch as u32;
    if code <= 0xFF {
        code as usize
    } else {
        b'?' as usize
    }
}

#[inline]
pub fn get_glyph(ch: char) -> [i8; GLYPH_PIXELS] {
    GLYPHS[glyph_index(ch)]
}

#[inline]
pub fn get_glyph_ref(ch: char) -> &'static [i8; GLYPH_PIXELS] {
    &GLYPHS[glyph_index(ch)]
}